let HighValueServers = (_GetWatchlist('ServidoresCriticos_PCI')
    | project HostName, Environment, Criticality);
SecurityEvent
| where EventID == 4625
| lookup kind=inner HighValueServers on $left.Computer == $right.HostName

let MaliciousIPs = externaldata(IPAddress: string, ThreatType: string)
[@"https://threatfeed.contoso.com/iocs/malicious_ips.csv"] with (format="csv", ignoreFirstRecord=true);
DeviceNetworkEvents
| where RemoteIP in (MaliciousIPs)
